<script setup>
import {onMounted,reactive,ref} from 'vue';import AdminNavigation from '../components/AdminNavigation.vue';import {request} from '../services/api';import {formatMoney as money} from '../utils/money';
const current=ref(null),boxes=ref([]),selected=ref(null),movements=ref([]),busy=ref(false),error=ref(''),notice=ref(''),confirmClose=ref(false);
const form=reactive({montoInicial:'0',efectivoContado:''});const name=p=>p?`${p.nombres} ${p.apellidos}`:'No disponible';const date=d=>new Date(d).toLocaleString('es-GT',{timeZone:'America/Guatemala'});
async function load(){try{boxes.value=await request('/cajas');try{current.value=await request('/cajas/actual');}catch(e){if(e.status!==404)throw e;current.value=null;}}catch(e){error.value=e.message;}}
async function open(){busy.value=true;error.value='';notice.value='';try{await request('/cajas/abrir',{method:'POST',body:JSON.stringify({montoInicial:form.montoInicial})});notice.value='Caja abierta. Ya puedes registrar pagos.';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function detail(id){error.value='';try{const [box,payments]=await Promise.all([request('/cajas/'+id),request('/cajas/'+id+'/movimientos')]);selected.value=box;movements.value=payments;}catch(e){error.value=e.message;}}
async function close(){busy.value=true;error.value='';notice.value='';try{const box=await request('/cajas/'+current.value._id+'/cerrar',{method:'POST',body:JSON.stringify({efectivoContado:form.efectivoContado})});confirmClose.value=false;form.efectivoContado='';notice.value='Caja cerrada. El cierre queda guardado y no admite nuevos movimientos.';await load();await detail(box._id);}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template>
<section class="page-heading"><p class="eyebrow">ADMINISTRACIÓN</p><h1>Caja diaria</h1><p class="intro">Abre tu caja, revisa los cobros y registra el cierre con el efectivo contado.</p></section><AdminNavigation/>
<p v-if="error" class="feedback error" role="alert">{{error}}</p><p v-if="notice" class="feedback success" role="status">{{notice}}</p>
<section class="form-panel" v-if="!current"><h2>Abrir mi caja</h2><form @submit.prevent="open"><fieldset :disabled="busy"><label for="cash-initial">Monto inicial en quetzales</label><input id="cash-initial" type="number" step="0.01" min="0" v-model="form.montoInicial" required><button class="button">{{busy?'Abriendo…':'Abrir caja'}}</button></fieldset></form></section>
<section class="form-panel" v-else><h2>Mi caja abierta</h2><p>Apertura: {{date(current.abiertaEn)}}</p><div class="totals"><p>Monto inicial <strong>{{money(current.montoInicialCentavos)}}</strong></p><p>Efectivo <strong>{{money(current.resumen.totalEfectivoCentavos)}}</strong></p><p>Transferencias <strong>{{money(current.resumen.totalTransferenciasCentavos)}}</strong></p><p>Tarjeta <strong>{{money(current.resumen.totalTarjetaCentavos)}}</strong></p><p>Ingresos <strong>{{money(current.resumen.totalIngresosCentavos)}}</strong></p><p>Efectivo esperado <strong>{{money(current.resumen.efectivoEsperadoCentavos)}}</strong></p></div>
<div class="actions"><RouterLink class="button" to="/admin/pagos">Registrar pagos</RouterLink><button class="button secondary" :disabled="busy" @click="detail(current._id)">Ver movimientos</button><button class="button secondary" :disabled="busy" @click="load">Actualizar totales</button></div>
<form @submit.prevent="confirmClose=true" v-if="!confirmClose"><label for="cash-counted">Efectivo contado en quetzales</label><input id="cash-counted" type="number" step="0.01" min="0" v-model="form.efectivoContado" required><button class="button secondary" :disabled="busy">Revisar cierre</button></form>
<div v-else><h3>Confirmar cierre</h3><p>Efectivo contado: {{money(Math.round(Number(form.efectivoContado)*100))}}. El servidor calculará los totales definitivos. El cierre bloquea nuevos cobros y anulaciones.</p><div class="actions"><button class="button" :disabled="busy" @click="close">{{busy?'Cerrando…':'Confirmar cierre de caja'}}</button><button class="button secondary" :disabled="busy" @click="confirmClose=false">Volver</button></div></div></section>
<section class="list-panel"><h2>Historial de cajas</h2><p>El administrador puede consultar todas las cajas. Recepción consulta únicamente las propias.</p><p v-if="!boxes.length">No hay cajas registradas.</p><ul class="admin-services"><li v-for="b in boxes" :key="b._id"><div class="service-line"><h3>{{name(b.responsable)}}</h3><span class="badge">{{b.estado}}</span></div><p>{{date(b.abiertaEn)}} · Ingresos {{money(b.resumen.totalIngresosCentavos)}}</p><button class="text-button" :disabled="busy" @click="detail(b._id)">Ver detalle y movimientos</button></li></ul></section>
<section class="list-panel" v-if="selected"><h2>Detalle de caja {{selected.estado.toLowerCase()}}</h2><p>{{name(selected.responsable)}} · {{date(selected.abiertaEn)}}</p><p>Monto inicial {{money(selected.montoInicialCentavos)}} · Ingresos {{money(selected.resumen.totalIngresosCentavos)}}</p><p>Efectivo {{money(selected.resumen.totalEfectivoCentavos)}} · Transferencias {{money(selected.resumen.totalTransferenciasCentavos)}} · Tarjeta {{money(selected.resumen.totalTarjetaCentavos)}}</p>
<template v-if="selected.cierre"><h3>Cierre guardado</h3><p>{{date(selected.cierre.cerradoEn)}}</p><p>Esperado {{money(selected.cierre.efectivoEsperadoCentavos)}} · Contado {{money(selected.cierre.efectivoContadoCentavos)}}</p><p><strong>{{selected.cierre.diferenciaCentavos<0?'Faltante':selected.cierre.diferenciaCentavos>0?'Sobrante':'Sin diferencia'}}: {{money(Math.abs(selected.cierre.diferenciaCentavos))}}</strong></p></template>
<h3>Movimientos</h3><p v-if="!movements.length">Sin movimientos.</p><ul class="admin-services"><li v-for="p in movements" :key="p._id"><p>{{money(p.montoCentavos)}} · {{p.metodo}} · {{p.estado}} · {{date(p.registradoEn)}}</p><p v-if="p.motivoAnulacion">Anulación: {{p.motivoAnulacion}}</p><RouterLink :to="'/admin/pagos/'+p._id+'/comprobante'">Ver comprobante</RouterLink></li></ul></section>
</template>
<style scoped>.form-panel,.list-panel{margin-bottom:20px}.totals{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.totals p{display:flex;flex-direction:column;gap:6px}</style>
